// Deterministic real-operand audit, independent of any GPU scheduling.
#define main generated_partial_matrix_audit_main
#include "tests/native/partial_matrix_group_host.cpp"
#undef main
#include <fstream>
#include <iostream>
#include <stdexcept>

std::vector<uint16_t> read_words(const char* path, size_t words) {
    std::ifstream f(path,std::ios::binary|std::ios::ate);
    if (!f || f.tellg()!=std::streamoff(words*2u)) throw std::runtime_error("capture extent");
    std::vector<uint16_t> result(words); f.seekg(0);
    f.read(reinterpret_cast<char*>(result.data()),std::streamsize(words*2u));
    if (!f) throw std::runtime_error("capture read");
    return result;
}

int main(int argc,char** argv) try {
    if (argc!=5) throw std::runtime_error("qkv|out INPUT WEIGHT REFERENCE");
    const std::string mode=argv[1];
    if (mode!="qkv" && mode!="out") throw std::runtime_error("mode");
    const unsigned rows=mode=="qkv"?8192u:2048u,width=mode=="qkv"?2048u:4096u;
    const auto inputs=read_words(argv[2],size_t(7169u)*width);
    const auto weights=read_words(argv[3],size_t(rows)*width);
    const auto reference=read_words(argv[4],size_t(mode=="qkv"?7169u:8192u)*rows);
    std::vector<unsigned> xf(7169u,1u),wf(rows,1u);
    uint64_t good_x=0u,good_w=0u;
    for (unsigned side=0u;side<2u;++side) {
        const auto& values=side?weights:inputs; auto& flags=side?wf:xf;
        for (unsigned row=0u;row<flags.size();++row) {
            for (unsigned k=0u;k<width;++k)
                flags[row]&=qrt_sm121_narrow_f32_carry::eligible(values[size_t(row)*width+k]);
            (side?good_w:good_x)+=flags[row];
        }
    }
    Counts counts; uint64_t eligible=0u,dots=0u;
    for (unsigned ts=0u;ts<128u;++ts) {
        const unsigned token=ts*8191u/127u,source_token=token%7169u;
        for (unsigned ws=0u;ws<64u;++ws) {
            // Rotate the row phase to avoid using one repeated channel subset.
            const unsigned row=(ws*rows/64u+ts*131u)%rows;
            const uint16_t* a=inputs.data()+size_t(source_token)*width;
            const uint16_t* b=weights.data()+size_t(row)*width;
            const bool admitted=xf[source_token]&&wf[row];
            original::Value carry{0u,-133,false}; float value=0.0f;
            for (unsigned g=0u;g<width/16u;++g) {
                if (admitted) value=group(value,carry,a+g*16u,b+g*16u,counts);
                else {
                    original::Value terms[17];terms[0]=carry;
                    for (unsigned i=0u;i<16u;++i)
                        terms[i+1u]=original::multiply_bf16(a[g*16u+i],b[g*16u+i],-133);
                    carry=original::group_sum<26,-133>(terms,17u);
                    value=original::value_to_float(carry);
                }
            }
            const uint32_t bits=matrix::f32::bits(value);
            const uint16_t rounded=uint16_t((bits+0x7fffu+((bits>>16u)&1u))>>16u);
            const size_t ref=(mode=="qkv"?size_t(source_token):size_t(token))*rows+row;
            if (rounded!=reference[ref]) {
                std::cerr<<"reference mismatch token="<<token<<" row="<<row
                    <<" actual="<<rounded<<" expected="<<reference[ref]<<'\n';
                return 3;
            }
            ++dots; eligible+=admitted;
        }
    }
    std::cout<<"{\"kind\":\"captured_projection_partial_matrix_host_sample\",\"mode\":\""<<mode
        <<"\",\"rows\":"<<rows<<",\"tokens\":8192,\"k\":"<<width
        <<",\"source_capture_tokens\":7169,\"repeated_rows\":1023,\"sampled_dots\":"<<dots
        <<",\"admitted_input_rows\":"<<good_x<<",\"admitted_weight_rows\":"<<good_w
        <<",\"domain_eligible_dots\":"<<eligible<<",\"ordered_groups\":"<<counts.groups
        <<",\"original_matrix_admitted\":"<<counts.original_admitted
        <<",\"additional_remainder_admitted\":"<<counts.remainder_admitted
        <<",\"additional_partial_admitted\":"<<counts.partial_admitted
        <<",\"partial_scalar_products\":"<<counts.sparse_products
        <<",\"original_narrow_fallback\":"<<counts.rejected
        <<",\"lossless_prepared_words\":"<<counts.words
        <<",\"raw_carry_mismatches\":0,\"gb10_sampled_bf16_mismatches\":0"
        <<",\"host_arithmetic_only\":true,\"gpu_executed\":false,\"inference_acceptance\":false}\n";
} catch (const std::exception& e) { std::cerr<<e.what()<<'\n';return 2; }
